mapper.select:
SELECT id, scheme_id, sku_id, factory_id, quantity, remark, sort_order, sku_snapshot_json, created_at, updated_at FROM scheme_item WHERE scheme_id IN
#{id}
ORDER BY scheme_id, sort_order, id

SELECT COALESCE(SUM(CAST(JSON_UNQUOTE(JSON_EXTRACT(sku_snapshot_json,'$.prices.dailyRentPriceFen')) AS DECIMAL(30,0))*quantity),0) AS daily_rent_fen,
  COALESCE(SUM(CAST(JSON_UNQUOTE(JSON_EXTRACT(sku_snapshot_json,'$.prices.depositAmountFen')) AS DECIMAL(30,0))*quantity),0) AS deposit_fen
FROM scheme_item WHERE scheme_id=#{schemeId}

  AND id NOT IN #{id}

mapper.update:
UPDATE scheme_item
SET quantity=#{row.quantity},
  remark=#{row.remark},
  sort_order=#{row.sortOrder},
  updated_at=#{row.updatedAt}
WHERE scheme_id=#{row.schemeId}
  AND id=#{row.id}

mapper.delete:
DELETE FROM scheme_item
WHERE scheme_id=#{schemeId}
  AND id=#{id}

mapper.update:
UPDATE scheme_share
SET share_status='disabled',
  updated_at=#{now}
WHERE scheme_id=#{id}
  AND share_status='active'

mapper.select:
SELECT id,
  scheme_id,
  content_version,
  hide_price,
  snapshot_json,
  created_at
FROM scheme_share_snapshot
WHERE scheme_id=#{schemeId}
  AND content_version=#{version}
  AND hide_price=#{hidePrice}
